int active()
{
    int ret = next active();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        SalesLine salesLineLocal = this.cursor();
        if (salesLineLocal.IsFreeItemLine)
        {
            GUPFreeItemLine gupFreeItemLine = GUPFreeItemLine::find(salesLineLocal.GUPFreeItemLineRecId);
            this.formRun().design().controlName(formControlStr(SalesTable, ProductDimensions)).enabled(!gupFreeItemLine.Variant);
        }
        else
        {
            this.formRun().design().controlName(formControlStr(SalesTable, ProductDimensions)).enabled(true);
        }
    }
    return ret;
}
